202: void GBTree::DoBoost(DMatrix* p_fmat, linalg::Matrix<GradientPair>* in_gpair,
203:                      PredictionCacheEntry* predt, ObjFunction const* obj) {
204:   if (model_.learner_model_param->IsVectorLeaf()) {
205:     CHECK(tparam_.tree_method == TreeMethod::kHist || tparam_.tree_method == TreeMethod::kAuto)
206:         << "Only the hist tree method is supported for building multi-target trees with vector "
207:            "leaf.";
208:     CHECK(ctx_->IsCPU()) << "GPU is not yet supported for vector leaf.";
209:   }
210: 
211:   TreesOneIter new_trees;
212:   bst_target_t const n_groups = model_.learner_model_param->OutputLength();
213:   monitor_.Start("BoostNewTrees");
214: 
215:   predt->predictions.SetDevice(ctx_->Device());
216:   auto out = linalg::MakeTensorView(ctx_, &predt->predictions, p_fmat->Info().num_row_,
217:                                     model_.learner_model_param->OutputLength());
218:   CHECK_NE(n_groups, 0);
219: 
220:   if (!p_fmat->SingleColBlock() && obj->Task().UpdateTreeLeaf()) {
221:     LOG(FATAL) << "Current objective doesn't support external memory.";
222:   }
223: 
224:   // The node position for each row, 1 HDV for each tree in the forest.  Note that the
225:   // position is negated if the row is sampled out.
226:   std::vector<HostDeviceVector<bst_node_t>> node_position;
227: 
228:   if (model_.learner_model_param->IsVectorLeaf()) {
229:     TreesOneGroup ret;
230:     BoostNewTrees(in_gpair, p_fmat, 0, &node_position, &ret);
231:     UpdateTreeLeaf(p_fmat, predt->predictions, obj, 0, node_position, &ret);
232:     std::size_t num_new_trees = ret.size();
233:     new_trees.push_back(std::move(ret));
234:     if (updaters_.size() > 0 && num_new_trees == 1 && predt->predictions.Size() > 0 &&
235:         updaters_.back()->UpdatePredictionCache(p_fmat, out)) {
236:       predt->Update(1);
237:     }
238:   } else if (model_.learner_model_param->OutputLength() == 1u) {
239:     TreesOneGroup ret;
240:     BoostNewTrees(in_gpair, p_fmat, 0, &node_position, &ret);
241:     UpdateTreeLeaf(p_fmat, predt->predictions, obj, 0, node_position, &ret);
242:     const size_t num_new_trees = ret.size();
243:     new_trees.push_back(std::move(ret));
244:     if (updaters_.size() > 0 && num_new_trees == 1 && predt->predictions.Size() > 0 &&
245:         updaters_.back()->UpdatePredictionCache(p_fmat, out)) {
246:       predt->Update(1);
247:     }
248:   } else {
249:     CHECK_EQ(in_gpair->Size() % n_groups, 0U) << "must have exactly ngroup * nrow gpairs";
250:     linalg::Matrix<GradientPair> tmp{{in_gpair->Shape(0), static_cast<std::size_t>(1ul)},
251:                                      ctx_->Device()};
252:     bool update_predict = true;
253:     for (bst_target_t gid = 0; gid < n_groups; ++gid) {
254:       node_position.clear();
255:       CopyGradient(ctx_, in_gpair, gid, &tmp);
256:       TreesOneGroup ret;
257:       BoostNewTrees(&tmp, p_fmat, gid, &node_position, &ret);
258:       UpdateTreeLeaf(p_fmat, predt->predictions, obj, gid, node_position, &ret);
259:       const size_t num_new_trees = ret.size();
260:       new_trees.push_back(std::move(ret));
261:       auto v_predt = out.Slice(linalg::All(), linalg::Range(gid, gid + 1));
262:       if (!(updaters_.size() > 0 && predt->predictions.Size() > 0 && num_new_trees == 1 &&
263:             updaters_.back()->UpdatePredictionCache(p_fmat, v_predt))) {
264:         update_predict = false;
265:       }
266:     }
267:     if (update_predict) {
268:       predt->Update(1);
269:     }

240: // calculate the cost of loss function
241: template <typename TrainingParams, typename T>
242: XGBOOST_DEVICE inline T CalcGainGivenWeight(const TrainingParams &p, T sum_grad, T sum_hess, T w) {
243:   return -(static_cast<T>(2.0) * sum_grad * w + (sum_hess + p.reg_lambda) * common::Sqr(w));
244: }
245: 
246: // calculate weight given the statistics
247: template <typename TrainingParams, typename T>
248: XGBOOST_DEVICE inline T CalcWeight(const TrainingParams &p, T sum_grad,
249:                                    T sum_hess) {
250:   if (sum_hess < p.min_child_weight || sum_hess <= 0.0) {
251:     return 0.0;
252:   }
253:   T dw = -ThresholdL1(sum_grad, p.reg_alpha) / (sum_hess + p.reg_lambda);
254:   if (p.max_delta_step != 0.0f && std::abs(dw) > p.max_delta_step) {
255:     dw = std::copysign(p.max_delta_step, dw);
256:   }
257:   return dw;
258: }
259: 
260: // calculate the cost of loss function
261: template <typename TrainingParams, typename T>
262: XGBOOST_DEVICE inline T CalcGain(const TrainingParams &p, T sum_grad, T sum_hess) {
263:   if (sum_hess < p.min_child_weight || sum_hess <= 0.0) {
264:     return static_cast<T>(0.0);
265:   }
266:   if (p.max_delta_step == 0.0f) {
267:     if (p.reg_alpha == 0.0f) {
268:       return common::Sqr(sum_grad) / (sum_hess + p.reg_lambda);
269:     } else {
270:       return common::Sqr(ThresholdL1(sum_grad, p.reg_alpha)) /
271:           (sum_hess + p.reg_lambda);
272:     }
273:   } else {
274:     T w = CalcWeight(p, sum_grad, sum_hess);
275:     T ret = CalcGainGivenWeight(p, sum_grad, sum_hess, w);
276:     if (p.reg_alpha == 0.0f) {
277:       return ret;
278:     } else {
279:       return ret + p.reg_alpha * std::abs(w);
280:     }
281:   }
282: }
