296: /**
297:  * \brief multi-target weight, calculated with learning rate.
298:  */
299: inline void CalcWeight(TrainParam const &p, linalg::VectorView<GradientPairPrecise const> grad_sum,
300:                        float eta, linalg::VectorView<float> out_w) {
301:   for (bst_target_t i = 0; i < out_w.Size(); ++i) {
302:     out_w(i) = CalcWeight(p, grad_sum(i).GetGrad(), grad_sum(i).GetHess()) * eta;
303:   }
304: }
