306: /**
307:  * \brief multi-target weight
308:  */
309: inline void CalcWeight(TrainParam const &p, linalg::VectorView<GradientPairPrecise const> grad_sum,
310:                        linalg::VectorView<float> out_w) {
311:   return CalcWeight(p, grad_sum, 1.0f, out_w);
312: }
