314: inline double CalcGainGivenWeight(TrainParam const &p,
315:                                   linalg::VectorView<GradientPairPrecise const> sum_grad,
316:                                   linalg::VectorView<float const> weight) {
317:   double gain{0};
318:   for (bst_target_t i = 0; i < weight.Size(); ++i) {
319:     gain += -weight(i) * ThresholdL1(sum_grad(i).GetGrad(), p.reg_alpha);
320:   }
321:   return gain;

502:   static double MultiCalcSplitGain(TrainParam const &param,
503:                                    linalg::VectorView<GradientPairPrecise const> left_sum,
504:                                    linalg::VectorView<GradientPairPrecise const> right_sum,
505:                                    linalg::VectorView<float> left_weight,
506:                                    linalg::VectorView<float> right_weight) {
507:     CalcWeight(param, left_sum, left_weight);
508:     CalcWeight(param, right_sum, right_weight);
509: 
510:     auto left_gain = CalcGainGivenWeight(param, left_sum, left_weight);
511:     auto right_gain = CalcGainGivenWeight(param, right_sum, right_weight);
512:     return left_gain + right_gain;
513:   }
