515:   template <bst_bin_t d_step>
516:   bool EnumerateSplit(common::HistogramCuts const &cut, bst_feature_t fidx,
517:                       common::Span<common::ConstGHistRow> hist,
518:                       linalg::VectorView<GradientPairPrecise const> parent_sum, double parent_gain,
519:                       SplitEntryContainer<std::vector<GradientPairPrecise>> *p_best) const {
520:     auto const &cut_ptr = cut.Ptrs();
521:     auto const &cut_val = cut.Values();
522:     auto const &min_val = cut.MinValues();
523: 
524:     auto sum = linalg::Empty<GradientPairPrecise>(ctx_, 2, hist.size());
525:     auto left_sum = sum.Slice(0, linalg::All());
526:     auto right_sum = sum.Slice(1, linalg::All());
527: 
528:     bst_bin_t ibegin, iend;
529:     if (d_step > 0) {
530:       ibegin = static_cast<bst_bin_t>(cut_ptr[fidx]);
531:       iend = static_cast<bst_bin_t>(cut_ptr[fidx + 1]);
532:     } else {
533:       ibegin = static_cast<bst_bin_t>(cut_ptr[fidx + 1]) - 1;
534:       iend = static_cast<bst_bin_t>(cut_ptr[fidx]) - 1;
535:     }
536:     const auto imin = static_cast<bst_bin_t>(cut_ptr[fidx]);
537: 
538:     auto n_targets = hist.size();
539:     auto weight = linalg::Empty<float>(ctx_, 2, n_targets);
540:     auto left_weight = weight.Slice(0, linalg::All());
541:     auto right_weight = weight.Slice(1, linalg::All());
542: 
543:     for (bst_bin_t i = ibegin; i != iend; i += d_step) {
544:       for (bst_target_t t = 0; t < n_targets; ++t) {
545:         auto t_hist = hist[t];
546:         auto t_p = parent_sum(t);
547:         left_sum(t) += t_hist[i];
548:         right_sum(t) = t_p - left_sum(t);
549:       }
550: 
551:       if (d_step > 0) {
552:         auto split_pt = cut_val[i];
553:         auto loss_chg =
554:             MultiCalcSplitGain(*param_, right_sum, left_sum, right_weight, left_weight) -
555:             parent_gain;
556:         p_best->Update(loss_chg, fidx, split_pt, d_step == -1, false, left_sum, right_sum);
557:       } else {
558:         float split_pt;
559:         if (i == imin) {
560:           split_pt = min_val[fidx];
561:         } else {
562:           split_pt = cut_val[i - 1];
563:         }
564:         auto loss_chg =
565:             MultiCalcSplitGain(*param_, right_sum, left_sum, left_weight, right_weight) -
566:             parent_gain;
567:         p_best->Update(loss_chg, fidx, split_pt, d_step == -1, false, right_sum, left_sum);
568:       }

