646:   linalg::Vector<float> InitRoot(linalg::VectorView<GradientPairPrecise const> root_sum) {
647:     auto n_targets = root_sum.Size();
648:     stats_ = linalg::Constant(ctx_, GradientPairPrecise{}, 1, n_targets);
649:     gain_.resize(1);
650: 
651:     linalg::Vector<float> weight({n_targets}, ctx_->Device());
652:     CalcWeight(*param_, root_sum, weight.HostView());
653:     auto root_gain = CalcGainGivenWeight(*param_, root_sum, weight.HostView());
654:     gain_.front() = root_gain;
655: 
656:     auto h_stats = stats_.HostView();
657:     std::copy(linalg::cbegin(root_sum), linalg::cend(root_sum), linalg::begin(h_stats));
658: 
659:     return weight;
660:   }
