662:   void ApplyTreeSplit(MultiExpandEntry const &candidate, RegTree *p_tree) {
663:     auto n_targets = p_tree->NumTargets();
664:     auto parent_sum = stats_.Slice(candidate.nid, linalg::All());
665: 
666:     auto weight = linalg::Empty<float>(ctx_, 3, n_targets);
667:     auto base_weight = weight.Slice(0, linalg::All());
668:     CalcWeight(*param_, parent_sum, base_weight);
669: 
670:     auto left_weight = weight.Slice(1, linalg::All());
671:     auto left_sum =
672:         linalg::MakeVec(candidate.split.left_sum.data(), candidate.split.left_sum.size());
673:     CalcWeight(*param_, left_sum, param_->learning_rate, left_weight);
674: 
675:     auto right_weight = weight.Slice(2, linalg::All());
676:     auto right_sum =
677:         linalg::MakeVec(candidate.split.right_sum.data(), candidate.split.right_sum.size());
678:     CalcWeight(*param_, right_sum, param_->learning_rate, right_weight);
679: 
680:     p_tree->ExpandNode(candidate.nid, candidate.split.SplitIndex(), candidate.split.split_value,
681:                        candidate.split.DefaultLeft(), base_weight, left_weight, right_weight);
682:     CHECK(p_tree->IsMultiTarget());
683:     auto left_child = p_tree->LeftChild(candidate.nid);
684:     CHECK_GT(left_child, candidate.nid);
685:     auto right_child = p_tree->RightChild(candidate.nid);
686:     CHECK_GT(right_child, candidate.nid);
687: 
688:     std::size_t n_nodes = p_tree->Size();
689:     gain_.resize(n_nodes);
690:     // Re-calculate weight without learning rate.
691:     CalcWeight(*param_, left_sum, left_weight);
692:     CalcWeight(*param_, right_sum, right_weight);
693:     gain_[left_child] = CalcGainGivenWeight(*param_, left_sum, left_weight);
694:     gain_[right_child] = CalcGainGivenWeight(*param_, right_sum, right_weight);

198:   [[nodiscard]] bool IsValidImpl(TrainParam const& param, bst_node_t num_leaves) const {
199:     if (split.loss_chg <= kRtEps) return false;
200:     auto is_zero = [](auto const& sum) {
201:       return std::all_of(sum.cbegin(), sum.cend(),
202:                          [&](auto const& g) { return g.GetHess() - .0 == .0; });
203:     };
204:     if (is_zero(split.left_sum) || is_zero(split.right_sum)) {
205:       return false;
206:     }
207:     if (split.loss_chg < param.min_split_loss) {
208:       return false;
209:     }
210:     if (param.max_depth > 0 && depth == param.max_depth) {
211:       return false;
212:     }
213:     if (param.max_leaves > 0 && num_leaves == param.max_leaves) {
214:       return false;
215:     }
216:     return true;

