871:   void PredictLeaf(DMatrix *p_fmat, HostDeviceVector<bst_float> *out_preds,
872:                    const gbm::GBTreeModel &model, unsigned ntree_limit) const override {
873:     auto const n_threads = this->ctx_->Threads();
874:     // number of valid trees
875:     if (ntree_limit == 0 || ntree_limit > model.trees.size()) {
876:       ntree_limit = static_cast<unsigned>(model.trees.size());
877:     }
878:     const MetaInfo &info = p_fmat->Info();
879:     std::vector<bst_float> &preds = out_preds->HostVector();
880:     preds.resize(info.num_row_ * ntree_limit);
881: 
882:     if (p_fmat->Info().IsColumnSplit()) {
883:       CHECK(!model.learner_model_param->IsVectorLeaf())
884:           << "Predict leaf with column split" << MTNotImplemented();
885: 
886:       ColumnSplitHelper helper(n_threads, model, 0, ntree_limit);
887:       helper.PredictLeaf(ctx_, p_fmat, &preds);
888:       return;
889:     }
890: 
891:     std::vector<RegTree::FVec> feat_vecs;
892:     const int num_feature = model.learner_model_param->num_feature;
893:     InitThreadTemp(n_threads, &feat_vecs);
894:     // start collecting the prediction
895:     for (const auto &batch : p_fmat->GetBatches<SparsePage>()) {
896:       // parallel over local batch
897:       auto page = batch.GetView();
898:       common::ParallelFor(page.Size(), n_threads, [&](auto i) {
899:         const int tid = omp_get_thread_num();
900:         auto ridx = static_cast<size_t>(batch.base_rowid + i);
901:         RegTree::FVec &feats = feat_vecs[tid];
902:         if (feats.Size() == 0) {
903:           feats.Init(num_feature);
904:         }
905:         feats.Fill(page[i]);
906:         for (std::uint32_t j = 0; j < ntree_limit; ++j) {
907:           auto const &tree = *model.trees[j];
908:           auto const &cats = tree.GetCategoriesMatrix();
909:           bst_node_t nidx;
910:           if (tree.IsMultiTarget()) {
911:             nidx = multi::GetLeafIndex<true, true>(*tree.GetMultiTargetTree(), feats, cats);
912:           } else {
913:             nidx = scalar::GetLeafIndex<true, true>(tree, feats, cats);
914:           }
915:           preds[ridx * ntree_limit + j] = static_cast<bst_float>(nidx);
916:         }
917:         feats.Drop();
918:       });
919:     }
920:   }
